class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        def representations(digits: str) -> List[str]:
            if len(digits) == 1:
                return [digits]

            if digits[0] == "0":
                return [] if digits[-1] == "0" else ["0." + digits[1:]]

            result = [digits]
            if digits[-1] != "0":
                for i in range(1, len(digits)):
                    result.append(digits[:i] + "." + digits[i:])
            return result

        digits = s[1:-1]
        answer = []

        for split in range(1, len(digits)):
            left = representations(digits[:split])
            right = representations(digits[split:])
            for x in left:
                for y in right:
                    answer.append(f"({x}, {y})")

        return answer
