class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        roof = m * n
        parent = list(range(roof + 1))
        size = [1] * (roof + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            a, b = find(a), find(b)
            if a == b:
                return
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]

        remaining = [row[:] for row in grid]
        for r, c in hits:
            remaining[r][c] = 0

        # Build components after all hit locations have been erased.
        for r in range(m):
            for c in range(n):
                if remaining[r][c] == 0:
                    continue
                brick = r * n + c
                if r == 0:
                    union(brick, roof)
                elif remaining[r - 1][c]:
                    union(brick, brick - n)
                if c > 0 and remaining[r][c - 1]:
                    union(brick, brick - 1)

        result = [0] * len(hits)
        directions = ((-1, 0), (1, 0), (0, -1), (0, 1))

        # Restore bricks backward, counting newly roof-connected bricks.
        for i in range(len(hits) - 1, -1, -1):
            r, c = hits[i]
            if grid[r][c] == 0:
                continue

            before = size[find(roof)]
            remaining[r][c] = 1
            brick = r * n + c

            if r == 0:
                union(brick, roof)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and remaining[nr][nc]:
                    union(brick, nr * n + nc)

            result[i] = max(0, size[find(roof)] - before - 1)

        return result
