from typing import List


class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}

        for value in arr:
            count = 1
            for left in arr:
                if left * left > value:
                    break
                if value % left == 0:
                    right = value // left
                    if right in dp:
                        ways = dp[left] * dp[right]
                        if left != right:
                            ways *= 2
                        count = (count + ways) % MOD
            dp[value] = count

        return sum(dp.values()) % MOD
```

