from collections import deque


class MKAverage:

    def __init__(self, m: int, k: int):
        self.m = m
        self.k = k
        self.window = deque()
        self.limit = 100000
        self.counts = [0] * (self.limit + 1)
        self.sums = [0] * (self.limit + 1)
        self.top_bit = 1 << (self.limit.bit_length() - 1)

    def _update(self, value: int, delta: int) -> None:
        index = value
        while index <= self.limit:
            self.counts[index] += delta
            self.sums[index] += value * delta
            index += index & -index

    def _sum_smallest(self, rank: int) -> int:
        # Find the value containing the rank-th element using binary lifting.
        index = 0
        total = 0
        bit = self.top_bit

        while bit:
            next_index = index + bit
            if next_index <= self.limit and self.counts[next_index] < rank:
                rank -= self.counts[next_index]
                total += self.sums[next_index]
                index = next_index
            bit >>= 1

        # Only the required copies of the boundary value are included.
        return total + rank * (index + 1)

    def addElement(self, num: int) -> None:
        self.window.append(num)
        self._update(num, 1)

        if len(self.window) > self.m:
            self._update(self.window.popleft(), -1)

    def calculateMKAverage(self) -> int:
        if len(self.window) < self.m:
            return -1

        middle_sum = (
            self._sum_smallest(self.m - self.k)
            - self._sum_smallest(self.k)
        )
        return middle_sum // (self.m - 2 * self.k)
```

