from typing import List


class Solution:
    def canCross(self, stones: List[int]) -> bool:
        for i in range(1, len(stones)):
            if stones[i] - stones[i - 1] > i:
                return False

        reachable = {position: set() for position in stones}
        reachable[0].add(0)
        destination = stones[-1]

        for position in stones:
            for last_jump in reachable[position]:
                for jump in (last_jump - 1, last_jump, last_jump + 1):
                    if jump <= 0:
                        continue

                    landing = position + jump
                    if landing == destination:
                        return True
                    if landing in reachable:
                        reachable[landing].add(jump)

        return False
```

