class Solution:
    def countMaxOrSubsets(self, nums: List[int]) -> int:
        target = 0
        for num in nums:
            target |= num

        n = len(nums)

        def dfs(index: int, current_or: int) -> int:
            if current_or == target:
                return 1 << (n - index)
            if index == n:
                return 0

            return (
                dfs(index + 1, current_or | nums[index])
                + dfs(index + 1, current_or)
            )

        return dfs(0, 0)
