from typing import List
from math import gcd
from functools import lru_cache


class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)
        pairs = [
            ((1 << i) | (1 << j), gcd(nums[i], nums[j]))
            for i in range(m)
            for j in range(i + 1, m)
        ]

        @lru_cache(None)
        def dp(mask: int) -> int:
            if mask == 0:
                return 0

            operation = mask.bit_count() // 2
            best = 0
            for pair_mask, value in pairs:
                if mask & pair_mask == pair_mask:
                    best = max(
                        best,
                        operation * value + dp(mask ^ pair_mask)
                    )
            return best

        return dp((1 << m) - 1)
```

