        if len(self.stack) < self.maxSize:
            self.stack.append(x)
            self.pending.append(0)

    def pop(self) -> int:
        if not self.stack:
            return -1

        extra = self.pending.pop()
        if self.pending:
            self.pending[-1] += extra

        return self.stack.pop() + extra

