from functools import lru_cache
from typing import List


class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        powers = [3 ** i for i in range(numSlots)]
        n = len(nums)

        @lru_cache(maxsize=None)
        def dp(index: int, state: int) -> int:
            if index == n:
                return 0

            best = 0
            for slot, power in enumerate(powers, start=1):
                # Each ternary digit records a slot's occupancy: 0, 1, or 2.
                if state // power % 3 < 2:
                    best = max(
                        best,
                        (nums[index] & slot) + dp(index + 1, state + power)
                    )
            return best

        return dp(0, 0)
