class Solution:
    def maxStudents(self, seats: List[List[str]]) -> int:
        n = len(seats[0])
        masks = [
            mask for mask in range(1 << n)
            if not (mask & (mask << 1))
        ]
        counts = {mask: mask.bit_count() for mask in masks}
        compatible = {
            mask: [
                prev for prev in masks
                if not (mask & (prev << 1))
                and not (mask & (prev >> 1))
            ]
            for mask in masks
        }

        dp = {0: 0}
        for row in seats:
            available = sum(
                1 << col for col, seat in enumerate(row) if seat == "."
            )
            next_dp = {}
            for mask in masks:
                if mask & available == mask:
                    next_dp[mask] = counts[mask] + max(
                        dp[prev]
                        for prev in compatible[mask]
                        if prev in dp
                    )
            dp = next_dp

        return max(dp.values())
