class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        infected = set(initial)
        visited = [False] * n
        saved = [0] * n

        # Find components consisting only of initially uninfected nodes.
        for start in range(n):
            if start in infected or visited[start]:
                continue

            stack = [start]
            visited[start] = True
            size = 0
            sources = set()

            while stack:
                node = stack.pop()
                size += 1

                for neighbor, connected in enumerate(graph[node]):
                    if not connected:
                        continue
                    if neighbor in infected:
                        sources.add(neighbor)
                    elif not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            # Only a unique infection source can save this entire component.
            if len(sources) == 1:
                source = next(iter(sources))
                saved[source] += size

        return min(initial, key=lambda node: (-saved[node], node))
