            start = next(
                ((r, c) for r, c in land if grid[r][c] == 1),
                None,
            )
            if start is None:
                return False

            seen = {start}
            stack = [start]

            while stack:
                r, c = stack.pop()
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < m
