class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):
            return -1

        def can_make(day: int) -> bool:
            bouquets = consecutive = 0

            for bloom in bloomDay:
                if bloom > day:
                    consecutive = 0
                else:
                    consecutive += 1
                    if consecutive == k:
                        bouquets += 1
                        consecutive = 0
                        if bouquets == m:
                            return True

            return False

        left, right = min(bloomDay), max(bloomDay)

        while left < right:
            mid = (left + right) // 2
            if can_make(mid):
                right = mid
            else:
                left = mid + 1

        return left
