        def best_linear(values: List[int]) -> int:
            negative_inf = float("-inf")
            prev2 = [0] + [negative_inf] * picks
            prev1 = [0] + [negative_inf] * picks

            for i, value in enumerate(values):
                current = prev1.copy()
