class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        result = []

        def remove(text, scan_start, removal_start, opening, closing):
            balance = 0

            for i in range(scan_start, len(text)):
                if text[i] == opening:
                    balance += 1
                elif text[i] == closing:
                    balance -= 1

                if balance >= 0:
                    continue

                # Remove one closing parenthesis from this invalid prefix.
                for j in range(removal_start, i + 1):
                    if text[j] == closing and (
                        j == removal_start or text[j - 1] != closing
                    ):
                        remove(
                            text[:j] + text[j + 1:],
                            i,
                            j,
                            opening,
                            closing,
                        )
                return

            reversed_text = text[::-1]
            if opening == "(":
                # Reverse the direction to remove excess opening parentheses.
                remove(reversed_text, 0, 0, ")", "(")
            else:
                result.append(reversed_text)

        remove(s, 0, 0, "(", ")")
        return result
