class Solution:
    def nextBeautifulNumber(self, n: int) -> int:
        min_length = len(str(n))
        max_length = min_length + 1
        best = 10 ** max_length

        for mask in range(1, 1 << max_length):
            digits = [
                d for d in range(1, max_length + 1)
                if mask & (1 << (d - 1))
            ]
            length = sum(digits)
            if not min_length <= length <= max_length:
                continue

            counts = [0] * (max_length + 1)
            for d in digits:
                counts[d] = d

            def search(value: int, remaining: int) -> None:
                nonlocal best

                if value * (10 ** remaining) >= best:
                    return
                if remaining == 0:
                    if value > n:
                        best = value
                    return

                for d in digits:
                    if counts[d]:
                        counts[d] -= 1
                        search(value * 10 + d, remaining - 1)
                        counts[d] += 1

            search(0, length)

        return best
