from functools import lru_cache


class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        n = len(s1)

        def build_prefix(s):
            prefix = [[0] * 26]
            for char in s:
                counts = prefix[-1].copy()
                counts[ord(char) - ord('a')] += 1
                prefix.append(counts)
            return prefix

        prefix1 = build_prefix(s1)
        prefix2 = build_prefix(s2)

        @lru_cache(None)
        def dfs(i, j, length):
            if s1[i:i + length] == s2[j:j + length]:
                return True

            for char in range(26):
                count1 = prefix1[i + length][char] - prefix1[i][char]
                count2 = prefix2[j + length][char] - prefix2[j][char]
                if count1 != count2:
                    return False

            for split in range(1, length):
                # Keep the two parts in the same order.
                if (dfs(i, j, split)
                        and dfs(i + split, j + split, length - split)):
                    return True

                # Swap the two parts.
                if (dfs(i, j + length - split, split)
                        and dfs(i + split, j, length - split)):
                    return True

            return False

        return dfs(0, 0, n)
