from typing import List


class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        values = sorted(set(nums))
        ranks = {value: i + 1 for i, value in enumerate(values)}
        size = len(values)
        tree = [0] * (size + 1)

        def update(value: int, delta: int) -> None:
            index = ranks[value]
            while index <= size:
                tree[index] += delta
                index += index & -index

        highest_bit = 1 << (size.bit_length() - 1)

        def kth(order: int) -> int:
            index = 0
            step = highest_bit
            while step:
                next_index = index + step
                if next_index <= size and tree[next_index] < order:
                    order -= tree[next_index]
                    index = next_index
                step >>= 1
            return values[index]

        def median() -> float:
            left = kth((k + 1) // 2)
            if k % 2:
                return float(left)
            return (left + kth(k // 2 + 1)) / 2.0

        for i in range(k):
            update(nums[i], 1)

        result = [median()]
        for i in range(k, len(nums)):
            update(nums[i - k], -1)
            update(nums[i], 1)
            result.append(median())

        return result
