class Solution:
    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        total = sum(nums)
        if total % k:
            return False
        if k == 1:
            return True

        target = total // k
        nums = sorted(nums)
        if nums[-1] > target:
            return False

        size = 1 << len(nums)
        dp = [-1] * size
        dp[0] = 0

        for mask in range(size):
            if dp[mask] == -1:
                continue

            remaining = target - dp[mask]
            for i, value in enumerate(nums):
                if value > remaining:
                    break

                bit = 1 << i
                if mask & bit:
                    continue

                next_mask = mask | bit
                if dp[next_mask] != -1:
                    continue

                dp[next_mask] = (dp[mask] + value) % target
                if next_mask == size - 1:
                    return True

        return False
