class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        regions = 4 * n * n
        parent = list(range(regions))
        size = [1] * regions

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            nonlocal regions
            a, b = find(a), find(b)
            if a == b:
                return
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]
            regions -= 1

        for r in range(n):
            for c in range(n):
                # Triangles: top, right, bottom, left.
                base = 4 * (r * n + c)
                char = grid[r][c]

                if char != "/":
                    union(base, base + 1)
                    union(base + 2, base + 3)

                if char != "\\":
                    union(base, base + 3)
                    union(base + 1, base + 2)

                if c + 1 < n:
                    union(base + 1, base + 7)

                if r + 1 < n:
                    union(base + 2, base + 4 * n)

        return regions
