class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        @lru_cache(None)
        def solve(size: int, first: int, second: int):
            if first + second == size + 1:
                return 1, 1

            # Reflect the row to reuse equivalent states.
            if first + second > size + 1:
                return solve(size, size + 1 - second, size + 1 - first)

            # Counts of advancing players before each distinguished player.
            counts = {(0, 0)}

            for left in range(1, (size + 1) // 2 + 1):
                right = size + 1 - left

                if left == first or right == first:
                    winners = (first,)
                elif left == second or right == second:
                    winners = (second,)
                elif left == right:
                    winners = (left,)
                else:
                    winners = (left, right)

                increments = {
                    (int(winner < first), int(winner < second))
                    for winner in winners
                }
                counts = {
                    (before_first + add_first, before_second + add_second)
                    for before_first, before_second in counts
                    for add_first, add_second in increments
                }

            earliest, latest = size, 0
            next_size = (size + 1) // 2

            for before_first, before_second in counts:
                low, high = solve(
                    next_size, before_first + 1, before_second + 1
                )
                earliest = min(earliest, low + 1)
                latest = max(latest, high + 1)

            return earliest, latest

        return list(solve(n, firstPlayer, secondPlayer))
