class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        values = set(nums)
        coprimes = {
            value: [other for other in values if gcd(value, other) == 1]
            for value in values
        }

        ans = [-1] * n
        ancestors = [[] for _ in range(51)]
        stack = [(0, -1, 0, False)]

        while stack:
            node, parent, depth, exiting = stack.pop()
            value = nums[node]

            if exiting:
                ancestors[value].pop()
                continue

            best_depth = -1
            for other in coprimes[value]:
                if ancestors[other]:
                    ancestor_depth, ancestor = ancestors[other][-1]
                    if ancestor_depth > best_depth:
                        best_depth = ancestor_depth
                        ans[node] = ancestor

            ancestors[value].append((depth, node))
            stack.append((node, parent, depth, True))

            for neighbor in graph[node]:
                if neighbor != parent:
                    stack.append((neighbor, node, depth + 1, False))

        return ans
