            return False

        letters = set("".join(words) + result)
        if len(letters) > 10:
            return False

        index = {char: i for i, char in enumerate(letters)}
        assignment = [-1] * len(letters)
        leading = [False] * len(letters)

        for word in words + [result]:
            if len(word) > 1:
                leading[index[word[0]]] = True

        result_ids = [index[char] for char in reversed(result)]
        columns = []

        for col in range(width):
            counts = {}
            for word in words:
                if col < len(word):
                    char = index[word[-1 - col]]
                    counts[char] = counts.get(char, 0) + 1

            columns.append(sorted(
                counts.items(),
                key=lambda item: (
                    item[0] == result_ids[col],
                    -item[1],
                    not leading[item[0]],
